app.post('/atividades', (req, res) => {
  if (!req.usuario) {
      return res.status(401).json({ erro: 'USUARIO_DESCONHECIDO', mensagem: 'Usuário não autenticado' });
  }
  if (req.usuario.papel !== 'organizacao') {
    return res.status(403).json({ erro: 'SOMENTE_ORGANIZACAO', mensagem: 'Apenas organização pode criar atividades' });
  }

  const { titulo, tipo, salaId, vagas, encontros } = req.body;

  if (!titulo || typeof titulo !== 'string' || titulo.trim() === '') {
      return res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'Título é obrigatório' });
  }

  // R11 (Vagas)
  if (!vagas || !Number.isInteger(vagas) || vagas < 1) {
      return res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'Vagas inválidas' });
  }

  // R12 (Sala)
  const salaStmt = db.prepare('SELECT capacidade FROM salas WHERE id = ?');
  const sala = salaStmt.get(salaId);
  if (!sala) {
      return res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'Sala inexistente' });
  }

  if (vagas > sala.capacidade) {
      return res.status(422).json({ erro: 'VAGAS_ACIMA_DA_CAPACIDADE', mensagem: 'Vagas acima da capacidade' });
  }

  if (tipo === 'palestra' && (!encontros || encontros.length !== 1)) {
      return res.status(422).json({ erro: 'QUANTIDADE_DE_ENCONTROS', mensagem: 'Palestra deve ter exatamente 1 encontro' });
  }

  if (tipo === 'minicurso' && (!encontros || encontros.length < 2 || encontros.length > 5)) {
      return res.status(422).json({ erro: 'QUANTIDADE_DE_ENCONTROS', mensagem: 'Minicurso deve ter entre 2 e 5 encontros' });
  }

  const id = `atv_${crypto.randomBytes(4).toString('hex')}`;

  db.prepare('INSERT INTO atividades (id, titulo, tipo, salaId, vagas) VALUES (?, ?, ?, ?, ?)')
    .run(id, titulo, tipo, salaId, vagas);

  const savedEncontros = [];
  let cargaHorariaMinutos = 0;
  for (const enc of encontros) {
      const encId = `enc_${crypto.randomBytes(4).toString('hex')}`;
      db.prepare('INSERT INTO encontros (id, atividadeId, inicio, fim) VALUES (?, ?, ?, ?)')
        .run(encId, id, enc.inicio, enc.fim);
      savedEncontros.push({ ...enc, id: encId });

      const inicio = new Date(enc.inicio);
      const fim = new Date(enc.fim);
      cargaHorariaMinutos += (fim - inicio) / 1000 / 60;
  }

  res.status(201).json({ 
      id, 
      titulo, 
      tipo, 
      salaId, 
      vagas, 
      encontros: savedEncontros, 
      cargaHorariaMinutos,
      situacao: 'prevista',
      ocupadas: 0,
      vagasRestantes: vagas,
      emEspera: 0
  });
});

